import CoreML
import Foundation
import Testing

@testable import CoreMLBackend

// Pins the Swift GLiNER2.5 classification preprocessing to the Python reference
// (`gliner2==2.0.0`'s own SchemaTransformer + ExtractorCollator). The fixture is
// generated by scratchpad/gliner-demo/gen_fixtures.py and committed next to the
// Mapper demo. Set CORELLM_GLINER_DIR to the downloaded model directory
// (models/gliner2-5-multi-coreml) to run; without it both tests skip.

private let glinerDirEnv = "CORELLM_GLINER_DIR"

private let glinerDir: URL? = ProcessInfo.processInfo.environment[glinerDirEnv]
    .flatMap { $0.isEmpty ? nil : URL(filePath: $0) }

private var glinerExists: Bool {
    guard let glinerDir else { return false }
    return FileManager.default.fileExists(
        atPath: glinerDir.appending(path: "tokenizer/tokenizer.json").path(percentEncoded: false))
}

private let glinerSkip: Comment = "set \(glinerDirEnv) to the gliner2-5-multi-coreml directory to run this test"

private struct ParityFixture: Decodable {
    struct Call: Decodable {
        var text: String
        var task: String
        var labels: [String]
        var input_ids: [Int32]
        var attention_mask: [Int32]
        var marker_indices: [Int32]
        var marker_mask: [Float]
        var probabilities: [Float]
    }
    struct Candidate: Decodable {
        var value: String
        var unit: String
        var window: String
    }
    struct Case: Decodable {
        var text: String
        var expected: [String: String]
        var numberCandidates: [Candidate]
    }
    var length: Int
    var maxOptions: Int
    var calls: [Call]
    var cases: [Case]
}

private func loadFixture() throws -> ParityFixture {
    // Tests run from the package root; the fixture lives with the demo that uses it.
    let url = URL(filePath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .deletingLastPathComponent()
        .appending(path: "CoreMLSamples/Demos/Mapper/Fixtures/gliner_parity.json")
    return try JSONDecoder().decode(ParityFixture.self, from: Data(contentsOf: url))
}

@Suite
struct GLiNERParitySuite {

    @Test("Swift preprocessing reproduces every Python input array", .enabled(if: glinerExists))
    func preprocessingParity() throws {
        let dir = try #require(glinerDir, glinerSkip)
        let fixture = try loadFixture()
        let encoder = try GLiNERSchemaEncoder(
            tokenizerFolder: dir.appending(path: "tokenizer"),
            bucketLength: fixture.length, maxOptions: fixture.maxOptions)

        var mismatches: [String] = []
        for (index, call) in fixture.calls.enumerated() {
            let got = try encoder.encode(text: call.text, task: call.task, labels: call.labels)
            if got.inputIDs != call.input_ids {
                let first = zip(got.inputIDs, call.input_ids).enumerated()
                    .first { $0.element.0 != $0.element.1 }
                mismatches.append(
                    "call \(index) \(call.text.prefix(16)) input_ids differ at \(first?.offset ?? -1) "
                        + "swift=\(first?.element.0 ?? -1) python=\(first?.element.1 ?? -1) tokens=\(got.tokens)")
            }
            if got.attentionMask != call.attention_mask {
                mismatches.append("call \(index) attention_mask differs")
            }
            if got.markerIndices != call.marker_indices {
                mismatches.append(
                    "call \(index) marker_indices swift=\(got.markerIndices) python=\(call.marker_indices)")
            }
            if got.markerMask != call.marker_mask {
                mismatches.append("call \(index) marker_mask differs")
            }
        }
        print(
            "GLiNER preprocessing parity: \(fixture.calls.count - mismatches.count)/\(fixture.calls.count) calls match")
        let report =
            "\(mismatches.count)/\(fixture.calls.count) mismatched:\n"
            + mismatches.prefix(5).joined(separator: "\n")
        #expect(mismatches.isEmpty, Comment(rawValue: report))
    }

    /// The number windows are cut by code on both sides; if they drift, the model
    /// silently sees different text. No model needed, so this one always runs.
    @Test("Swift number-candidate windows match Python")
    func numberCandidateParity() throws {
        let fixture = try loadFixture()
        var mismatches: [String] = []
        for testCase in fixture.cases {
            let got = MapperForm.numberCandidates(in: testCase.text)
            guard got.count == testCase.numberCandidates.count else {
                mismatches.append("\(testCase.text): \(got.count) candidates vs \(testCase.numberCandidates.count)")
                continue
            }
            for (swift, python) in zip(got, testCase.numberCandidates)
            where swift.value != python.value || swift.unit != python.unit || swift.window != python.window {
                mismatches.append(
                    "\(testCase.text): swift=(\(swift.value),\(swift.unit),\(swift.window)) "
                        + "python=(\(python.value),\(python.unit),\(python.window))")
            }
        }
        print("GLiNER number-candidate parity: \(fixture.cases.count) sentences, \(mismatches.count) mismatched")
        #expect(mismatches.isEmpty, Comment(rawValue: mismatches.prefix(5).joined(separator: "\n")))
    }

    @Test("Core ML scores match Python within fp16 noise", .enabled(if: glinerExists))
    func scoreParity() throws {
        let dir = try #require(glinerDir, glinerSkip)
        let fixture = try loadFixture()
        let classifier = try GLiNERClassifier(
            modelURL: dir.appending(path: "gliner2_multi_classification_fp16_L128_K8.mlpackage"),
            tokenizerFolder: dir.appending(path: "tokenizer"),
            bucketLength: fixture.length, maxOptions: fixture.maxOptions)

        var worst = Float(0)
        var worstDetail = ""
        var overBudget: [String] = []
        for (index, call) in fixture.calls.enumerated() {
            let scores = try classifier.scores(text: call.text, task: call.task, labels: call.labels)
            for (label, pair) in zip(call.labels, zip(scores, call.probabilities)) {
                let delta = abs(pair.0 - pair.1)
                if delta > worst {
                    worst = delta
                    worstDetail = "call \(index) \(call.task)/\(label) swift=\(pair.0) python=\(pair.1)"
                }
                if delta > 0.02 {
                    overBudget.append("call \(index) \(call.task)/\(label) Δ=\(delta)")
                }
            }
        }
        print("GLiNER score parity: \(fixture.calls.count) calls, worst Δ=\(worst) — \(worstDetail)")
        let report =
            "\(overBudget.count) scores exceed 0.02:\n"
            + overBudget.prefix(5).joined(separator: "\n")
        #expect(overBudget.isEmpty, Comment(rawValue: report))
    }
}
